/// One MC `MobSpawnSettings.SpawnerData` row: a weighted spawn
/// candidate plus its pack-size bounds (`minCount..=maxCount`, both
/// inclusive - `NaturalSpawner.spawnCategoryForPosition` rolls
/// `minCount + nextInt(1 + maxCount - minCount)` members per pack).
pub(crate) struct SpawnRow {
    pub(crate) kind: u8,
    pub(crate) weight: u32,
    pub(crate) min_count: u8,
    pub(crate) max_count: u8,
}

/// Per-bucket spawner lists split by MC `MobCategory` (the categories
/// that appear in the mapped biomes; `axolotls` + `misc` never do).
pub(crate) struct CategoryPools {
    pub(crate) monster: &'static [SpawnRow],
    pub(crate) creature: &'static [SpawnRow],
    pub(crate) ambient: &'static [SpawnRow],
    pub(crate) water_creature: &'static [SpawnRow],
    pub(crate) water_ambient: &'static [SpawnRow],
    pub(crate) underground_water_creature: &'static [SpawnRow],
}

